use altrun_probe::{migration::Migration,library::EntryKind};
#[test]fn migration_preserves_originals_preferences_and_history_without_enabling_integration(){let root=std::env::current_dir().unwrap().join("target/migration-fixture");std::fs::create_dir_all(&root).unwrap();let original="F7|utf8_query|web|搜索|https://example.com/?q={%p}\n\n备注\nnp,记事本,notepad.exe\n";std::fs::write(root.join("ShortCutList.txt"),original).unwrap();std::fs::write(root.join("ALTRun.ini"),"[Config]\nAutoRun=1\nHotKey1=Alt+R\nRememberFavouratMatch=1\n[GUI]\nFormWidth=600\n[DEBUG]\nLatestList=2,0\nHandleID=1234\n").unwrap();std::fs::write(root.join("FavoriteList.txt"),"n|记事本\n").unwrap();std::fs::write(root.join("ParamHistory.txt"),"7|hello world\n").unwrap();let import=Migration::read(&root,false).unwrap();assert_eq!(import.entries.len(),4);assert_eq!(import.entries[1].kind,EntryKind::Separator);assert_eq!(import.preferences.get("HotKey1"),"Ctrl+Alt+R");assert!(!import.preferences.flag("AutoRun"));assert_eq!(import.preferences.number("FormWidth"),420);assert_eq!(import.usage.parameters["*"][0],"hello world");assert_eq!(import.usage.recent[0],import.entries[3].id);let output=root.join(altrun_probe::library::new_id());let data=import.write_new(&output).unwrap();assert!(data.exists());assert_eq!(std::fs::read_to_string(output.join("originals/ShortCutList.txt")).unwrap(),original);assert!(import.write_new(&root).is_err());assert_eq!(std::fs::read_to_string(root.join("ShortCutList.txt")).unwrap(),original);}
